      ...close([['I can say what weather I like.', 'I like sunny weather.'], ['I can say why.', 'because I can play outside'], ["I can say what weather I don't like.", "I don't like rainy weather."]], { img: '19667', q: "It's 30 degrees! Is it hot or cold?", ko: '30도면 더울까요, 추울까요? (004에서)' }),
